from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def purge_expired(t):
        expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            purge_expired(t)
            if key in cache:
                # update existing (still live) entry
                del cache[key]
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # evict LRU
            cache[key] = (value, t)
        elif op[0] == 'get':
            _, t, key = op
            purge_expired(t)
            if key in cache:
                value, wt = cache[key]
                del cache[key]
                cache[key] = (value, wt)  # move to end, keep original write time
                results.append(value)
            else:
                results.append(-1)
        else:
            raise ValueError("Unknown operation type: {}".format(op[0]))

    return results

